mapper.insert:
INSERT /*LGVATT50020.insertHoliday*/ INTO tb_att_holiday_info_n
( subsidiary_code					/* 해외법인코드 */
 ,time_and_attendance_yyyy			/* 휴일년도 */
 ,time_and_attendance_code			/* Attendance Code */
 ,holiday_date						/* 휴일 */
 ,holiday_code 						/* 휴일코드 */
 ,holiday_name 						/* 휴일명 */
 ,public_hours                      /* public hours HMT_20210323*/
 ,shift_type_codes                  /* Add shift_type_codes column HMT_20251201*/
 ,creation_user_id 					/* 사용자ID */
 ,creation_date 					/* 등록일자 */
 ,last_update_user_id 				/* 최종수정자ID */
 ,last_update_date 					/* 수정일자 */
) values
( #{subsidiaryCode}
 ,#{timeAndAttendanceYyyy}
 ,#{timeAndAttendanceCode}
 ,trunc(TO_DATE(#{holidayDate}, 'YYYY-MM-DD'))
 ,#{holidayCode}
 ,(	SELECT distinct lcm.common_code_name
	FROM lgcom_common_code_multi_lang_c lcm
	WHERE lcm.code_type_code = 'LGVHR_HOLIDAY_CODE' 
	AND lcm.common_code = #{holidayCode}
	group by lcm.common_code_name)
 ,#{publicHours}
 ,#{shiftTypeCodes}
 ,#{applicationUserId}
 ,trunc(sysdate)
 ,#{applicationUserId}
 ,trunc(sysdate)
)

mapper.delete:
		 DELETE FROM tb_att_holiday_info_n
		 WHERE subsidiary_code = #{subsidiaryCode}
		 AND time_and_attendance_yyyy = #{timeAndAttendanceYyyy}
         AND holiday_date = trunc(TO_DATE(#{beforeHolidayDate}, 'YYYY-MM-DD'))      /* 휴일 */
